% Include global constraints
include "globals.mzn";

% Sets
int: N = 5;

% Indices for children, countries, stories, and ages
set of int: IDX = 1..N;

% Children: 1=Bernice, 2=Carl, 3=Debby, 4=Sammy, 5=Ted
array[IDX] of string: child_names = ["Bernice", "Carl", "Debby", "Sammy", "Ted"];

% Countries: 1=Ethiopia, 2=Kazakhstan, 3=Lithuania, 4=Morocco, 5=Yemen
array[IDX] of string: country_names = ["Ethiopia", "Kazakhstan", "Lithuania", "Morocco", "Yemen"];

% Stories: 1=Burning bush, 2=Captivity, 3=Moses's youth, 4=Passover, 5=Ten Commandments
array[IDX] of string: story_names = ["Burning bush", "Captivity", "Moses's youth", "Passover", "Ten Commandments"];

% Ages: 1=3, 2=5, 3=7, 4=8, 5=10
array[IDX] of int: age_values = [3,5,7,8,10];

% Decision variables:
% For each position i, the ith child is assigned:
% ages[i], countries[i], stories[i]
array[IDX] of var IDX: ages;      % index into age_values
array[IDX] of var IDX: countries; % index into country_names
array[IDX] of var IDX: stories;   % index into story_names

% All assignments are bijections
constraint all_different(ages);
constraint all_different(countries);
constraint all_different(stories);

% 1. Debby’s family is from Lithuania.
% Debby is child 3, Lithuania is country 3
constraint countries[3] = 3;

% 2. The child who told the story of the Passover is two years older than Bernice.
% Passover is story 4, Bernice is child 1
% ages[child_with_story_4] = ages[1] + 2 (in age_values)
constraint ages[ index_set(stories, 4) ] = ages[1] + 2;

% 3. The child whose family is from Yemen is younger than the child from the Ethiopian family.
% Yemen is country 5, Ethiopia is country 1
constraint ages[ index_set(countries, 5) ] < ages[ index_set(countries, 1) ];

% 4. The child from the Moroccan family is three years older than Ted.
% Morocco is country 4, Ted is child 5
constraint ages[ index_set(countries, 4) ] = ages[5] + 3;

% 5. Sammy is three years older than the child who told the story of Moses’s youth in the house of the Pharaoh.
% Sammy is child 4, Moses's youth is story 3
constraint ages[4] = ages[ index_set(stories, 3) ] + 3;

% Helper function: find the index of a value in an array
function var int: index_set(array[IDX] of var int: arr, int: val) =
    sum([i * bool2int(arr[i] = val) | i in IDX]);

solve satisfy;

output [
    "{",
    "\"ages\": [" ++ join(",", [show(ages[i]) | i in IDX]) ++ "],",
    "\"children\": [" ++ join(",", [show(i) | i in IDX]) ++ "],",
    "\"countries\": [" ++ join(",", [show(countries[i]) | i in IDX]) ++ "],",
    "\"stories\": [" ++ join(",", [show(stories[i]) | i in IDX]) ++ "]",
    "}"
];
```

