% Five people: Baker, Cooper, Fletcher, Miller, Smith
% Variables: floor number for each person (1..5)
% B: Baker, C: Cooper, F: Fletcher, M: Miller, S: Smith

include "globals.mzn";

% Decision variables: floor for each person
var 1..5: B; % Baker
var 1..5: C; % Cooper
var 1..5: F; % Fletcher
var 1..5: M; % Miller
var 1..5: S; % Smith

% All live on different floors
constraint all_different([B, C, F, M, S]);

% Baker does not live on the fifth floor
constraint B != 5;

% Cooper does not live on the first floor
constraint C != 1;

% Fletcher does not live on the first or fifth floor
constraint F != 1 /\ F != 5;

% Miller lives on a higher floor than does Cooper
constraint M > C;

% Smith does not live on a floor adjacent to Fletcher's
constraint abs(S - F) != 1;

% Fletcher does not live on a floor adjacent to Cooper's
constraint abs(F - C) != 1;

solve satisfy;

output [
    "{",
    join(",", [
        "\"B\": " ++ show(B),
        "\"C\": " ++ show(C),
        "\"F\": " ++ show(F),
        "\"M\": " ++ show(M),
        "\"S\": " ++ show(S)
    ]),
    "}"
];
```

