```minizinc
% Include the global constraints library
include "globals.mzn";

% Input data
int: num_people = 8;
array[1..num_people] of set of int: compatible = [
    {2, 3},
    {1, 6},
    {1, 4, 7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

% Decision variables:
% transplants[i,j] = 1 if person i donates to person j, 0 otherwise
array[1..num_people, 1..num_people] of var 0..1: transplants;

% Constraints:

% Only allow transplants along compatible edges (i cannot donate to themselves)
constraint
    forall(i in 1..num_people, j in 1..num_people) (
        (j in compatible[i] /\ i != j) -> (transplants[i,j] >= 0)
        /\
        (not (j in compatible[i]) \/ i = j) -> (transplants[i,j] = 0)
    );

% No person receives more than one kidney
constraint
    forall(j in 1..num_people) (
        sum(i in 1..num_people)(transplants[i,j]) <= 1
    );

% No person donates more than one kidney
constraint
    forall(i in 1..num_people) (
        sum(j in 1..num_people)(transplants[i,j]) <= 1
    );

% Anyone who gives a kidney must receive one (i.e., if i donates, i must also receive)
constraint
    forall(i in 1..num_people) (
        sum(j in 1..num_people)(transplants[i,j]) <= sum(k in 1..num_people)(transplants[k,i])
    );

% No self-donation
constraint
    forall(i in 1..num_people) (
        transplants[i,i] = 0
    );

% Objective: maximize the number of people who receive a kidney
var int: total_received = sum(j in 1..num_people)(min(1, sum(i in 1..num_people)(transplants[i,j])));

solve maximize total_received;

% Output as required: transplants as a list of lists
output [
    "{",
    "\"transplants\": [",
    join(",", [
        "[" ++ join(",", [show(transplants[i,j]) | j in 1..num_people]) ++ "]"
        | i in 1..num_people
    ]),
    "]",
    "}"
];
```

