% Include the global constraints library
include "globals.mzn";

% Size of the magic square
int: n = 4;

% The set of possible values in the square
set of int: Values = 1..n*n;

% The magic constant (sum for each row, column, and diagonal)
int: magic_sum = n * (n*n + 1) div 2;

% Decision variables: the magic square
array[1..n, 1..n] of var Values: square;

% All values must be different
constraint all_different([square[i,j] | i in 1..n, j in 1..n]);

% Each row must sum to magic_sum
constraint forall(i in 1..n) (
    sum(j in 1..n)(square[i,j]) = magic_sum
);

% Each column must sum to magic_sum
constraint forall(j in 1..n) (
    sum(i in 1..n)(square[i,j]) = magic_sum
);

% Main diagonal must sum to magic_sum
constraint sum(i in 1..n)(square[i,i]) = magic_sum;

% Anti-diagonal must sum to magic_sum
constraint sum(i in 1..n)(square[i, n-i+1]) = magic_sum;

solve satisfy;

output [
    "{",
    "\"square\": [",
    join(",", [ "[" ++ join(",", [show(square[i,j]) | j in 1..n]) ++ "]" | i in 1..n ]),
    "]",
    "}"
];
```

