% The number of males and females that have entered up to position i
array[1..n] of var 0..num_males: males_in;
array[1..n] of var 0..num_females: females_in;

% Initial values
constraint males_in[1] = 1 - sequence[1];
constraint females_in[1] = sequence[1];

% Cumulative counts
constraint forall(i in 2..n) (
    males_in[i] = males_in[i-1] + (1 - sequence[i]) /\
    females_in[i] = females_in[i-1] + sequence[i]
);

% Total males and females must match
constraint sum(i in 1..n)(sequence[i]) = num_females;
constraint sum(i in 1..n)(1 - sequence[i]) = num_males;

% At any time, the ratio of females to males in the room is no greater than 7/3
% That is: females_in[i] / males_in[i] <= 7/3
% To avoid division by zero, only check when males_in[i] > 0
constraint forall(i in 1..n where males_in[i] > 0) (
    3 * females_in[i] <= 7 * males_in[i]
);

solve satisfy;

output [
    "{",
    "\"sequence\": [" ++ join(",", [show(sequence[i]) | i in 1..n]) ++ "]",
    "}"
];
