% If guilty, lies: Crackitt is innocent
constraint (guilty[BILL] == 0) -> (guilty[CRACKITT] == 1);
constraint (guilty[BILL] == 1) -> (guilty[CRACKITT] == 0);

% CRACKITT: "No I wasn't."
% If innocent, tells the truth: Crackitt is innocent
% If guilty, lies: Crackitt is guilty
constraint (guilty[CRACKITT] == 0) -> (guilty[CRACKITT] == 0);
constraint (guilty[CRACKITT] == 1) -> (guilty[CRACKITT] == 1);

% DODGY: "If Crackitt did it, Bill did it with him."
% If innocent, tells the truth: (if Crackitt is guilty, then Bill is guilty)
% If guilty, lies: (if Crackitt is guilty, then Bill is not guilty)
constraint (guilty[DODGY] == 0) -> (guilty[CRACKITT] == 0 \/ guilty[BILL] == 1);
constraint (guilty[DODGY] == 1) -> (guilty[CRACKITT] == 0 \/ guilty[BILL] == 0);

