include "globals.mzn";

% Input data
int: num_slots = 6;
array[1..num_slots] of int: demands = [4, 8, 10, 7, 12, 4];

% Each bus can operate only 8 successive hours (i.e., 2 consecutive 4-hour slots)
% Decision variables: x[i] = number of buses starting their 8-hour shift at slot i
array[1..num_slots] of var 0..100: x;

% For each slot, the buses available are those that started in this slot or the previous slot
constraint
    forall(i in 1..num_slots) (
        let {
            int: prev = if i = 1 then num_slots else i-1
        } in
            x[i] + x[prev] >= demands[i]
    );

% Objective: minimize the total number of buses scheduled
solve minimize sum(i in 1..num_slots)(x[i]);

% Output in JSON format
output [
    "{",
    "\"x\": [" ++ join(",", [show(x[i]) | i in 1..num_slots]) ++ "]",
    "}"
];
```

