% N-Puzzle Problem in MiniZinc

include "globals.mzn";

% Input data
int: N = 20; % Number of steps to the solution
int: R = 3;  % Number of rows
int: C = 3;  % Number of columns
set of int: ROWS = 1..R;
set of int: COLS = 1..C;
set of int: TILES = 0..8; % 0 is the empty tile

array[ROWS, COLS] : puzzle_start = 
    array2d(ROWS, COLS, [
        0, 3, 6,
        2, 4, 8,
        1, 7, 5
    ]);

array[ROWS, COLS] : puzzle_end = 
    array2d(ROWS, COLS, [
        1, 2, 3,
        4, 5, 6,
        7, 8, 0
    ]);

% Decision variables
% steps[s, r, c] is the tile at row r, col c at step s (s=1 is start, s=N+1 is end)
array[1..N+1, ROWS, COLS] of var TILES: steps;

% Each step must be a permutation of the tiles 0..8
constraint
    forall(s in 1..N+1) (
        alldifferent([steps[s, r, c] | r in ROWS, c in COLS])
        /\
        forall(t in TILES) (
            count([steps[s, r, c] | r in ROWS, c in COLS], t) = 1
        )
    );

% Initial and final states
constraint
    forall(r in ROWS, c in COLS) (
        steps[1, r, c] = puzzle_start[r, c] /\
        steps[N+1, r, c] = puzzle_end[r, c]
    );

% Only one move per step: the empty tile (0) swaps with an adjacent tile
predicate is_adjacent(int: r1, int: c1, int: r2, int: c2) =
    (abs(r1 - r2) = 1 /\ c1 = c2) \/ (abs(c1 - c2) = 1 /\ r1 = r2);

constraint
    forall(s in 1..N) (
        let {
            % Find the position of the empty tile at step s and s+1
            var int: r0_s = sum([if steps[s, r, c] = 0 then r else 0 endif | r in ROWS, c in COLS]),
            var int: c0_s = sum([if steps[s, r, c] = 0 then c else 0 endif | r in ROWS, c in COLS]),
            var int: r0_sp = sum([if steps[s+1, r, c] = 0 then r else 0 endif | r in ROWS, c in COLS]),
            var int: c0_sp = sum([if steps[s+1, r, c] = 0 then c else 0 endif | r in ROWS, c in COLS])
        } in
        % The empty tile must move to an adjacent position
        is_adjacent(r0_s, c0_s, r0_sp, c0_sp)
        /\
        % All other tiles remain the same, except the tile that swaps with the empty tile
        forall(r in ROWS, c in COLS) (
            if (r = r0_s /\ c = c0_s) \/ (r = r0_sp /\ c = c0_sp) then
                true
            else
                steps[s, r, c] = steps[s+1, r, c]
            endif
        )
        /\
        % The tile that swaps with the empty tile moves into the empty position
        steps[s+1, r0_s, c0_s] = steps[s, r0_sp, c0_sp]
    );

solve satisfy;

% Output: steps as a list of N+1 2D matrices
output [
    "{",
    "\"steps\": [",
    join(",\n", [
        "[" ++
        join(",", [
            "[" ++ join(",", [show(steps[s, r, c]) | c in COLS]) ++ "]"
            | r in ROWS
        ]) ++ "]"
        | s in 1..N+1
    ]),
    "]",
    "}"
];
```

