include "globals.mzn";

% ----------------------
% Input data
% ----------------------
int: n = 4;
array[1..n] of int: widths = [3, 4, 2, 1];
array[1..n] of int: heights = [2, 3, 1, 4];

% ----------------------
% Decision Variables
% ----------------------

% Upper bounds for the container dimensions
int: max_width = sum(widths);
int: max_height = sum(heights);

% The dimensions of the larger rectangle
var 1..max_width: total_x;
var 1..max_height: total_y;

% The positions of the bottom-left corner of each item
array[1..n] of var 0..max_width: pos_x;
array[1..n] of var 0..max_height: pos_y;

% ----------------------
% Constraints
% ----------------------

% All items must be within the boundaries of the larger rectangle
constraint forall(i in 1..n) (
    pos_x[i] + widths[i] <= total_x /\
    pos_y[i] + heights[i] <= total_y
);

% No overlap between any two items
constraint forall(i, j in 1..n where i < j) (
    (pos_x[i] + widths[i] <= pos_x[j]) \/
    (pos_x[j] + widths[j] <= pos_x[i]) \/
    (pos_y[i] + heights[i] <= pos_y[j]) \/
    (pos_y[j] + heights[j] <= pos_y[i])
);

% Symmetry breaking: place the largest item at the origin
% (optional, but helps the solver)
int: largest = arg_max([widths[i]*heights[i] | i in 1..n]);
constraint pos_x[largest] = 0 /\ pos_y[largest] = 0;

% ----------------------
% Objective
% ----------------------

solve minimize total_x * total_y;

% ----------------------
% Output
% ----------------------

output [
    "{",
    "\"pos_x\": [" ++ join(",", [show(pos_x[i]) | i in 1..n]) ++ "],",
    "\"pos_y\": [" ++ join(",", [show(pos_y[i]) | i in 1..n]) ++ "],",
    "\"total_x\": " ++ show(total_x) ++ ",",
    "\"total_y\": " ++ show(total_y),
    "}"
];
