% Include the global constraints library
include "globals.mzn";

% Input data
int: max_rooms = 5;
array[1..4] of string: start_data = ["2024-05-01", "2024-05-02", "2024-05-03", "2024-05-04"];
array[1..4] of string: end_data = ["2024-05-05", "2024-05-06", "2024-05-07", "2024-05-08"];
array[1..4] of int: preassigned_room_data = [3, -1, -1, -1];

int: num_requests = 4;

% Helper function to convert date string "YYYY-MM-DD" to an integer (days since 2024-05-01)
function int: date_to_int(string: date) =
    let {
        int: year = str_to_int(substr(date,1,4)),
        int: month = str_to_int(substr(date,6,2)),
        int: day = str_to_int(substr(date,9,2)),
        int: base_year = 2024,
        int: base_month = 5,
        int: base_day = 1,
        array[1..12] of int: month_days = [31,28,31,30,31,30,31,31,30,31,30,31]
    } in
    (year - base_year) * 365
    + (sum([month_days[m] | m in base_month..month-1]) if month > base_month else 0)
    + (day - base_day);

% Convert start and end dates to integer days
array[1..num_requests] of int: start_days = [date_to_int(start_data[i]) | i in 1..num_requests];
array[1..num_requests] of int: end_days = [date_to_int(end_data[i]) | i in 1..num_requests];

% Decision variables: room assigned to each request (1..max_rooms)
array[1..num_requests] of var 1..max_rooms: room_assignments;

% Apply pre-assignments
constraint
    forall(i in 1..num_requests where preassigned_room_data[i] != -1) (
        room_assignments[i] = preassigned_room_data[i]
    );

% No two overlapping requests can be assigned to the same room
constraint
    forall(i, j in 1..num_requests where i < j) (
        let {
            % Requests i and j overlap if their intervals intersect
            bool: overlap = not (end_days[i] < start_days[j] \/ end_days[j] < start_days[i])
        } in
            overlap -> room_assignments[i] != room_assignments[j]
    );

solve satisfy;

output [
    "{",
    "\"room_assignments\": [" ++ join(",", [show(room_assignments[i]) | i in 1..num_requests]) ++ "]",
    "}"
];
