% Include the global constraints library
include "globals.mzn";

% Input data: coordinates of the cities
array[1..12, 1..2] of int: locations = 
    [|288, 149|288, 129|270, 133|256, 141|256, 163|246, 157|
      236, 169|228, 169|228, 148|220, 164|212, 172|204, 159|];

int: n = 12;
set of int: Cities = 1..n;

% Precompute the distance matrix (Euclidean distance, rounded to nearest int)
array[Cities, Cities] of int: dist = 
    array2d(Cities, Cities, [
        if i = j then 0 else
            let {
                var float: dx = float(locations[i,1] - locations[j,1]),
                var float: dy = float(locations[i,2] - locations[j,2])
            } in
                round(sqrt(dx*dx + dy*dy))
        endif
        | i in Cities, j in Cities
    ]);

% Decision variables
array[Cities] of var Cities: succ; % succ[i] is the city visited after city i
array[Cities] of var Cities: pred; % pred[i] is the city visited before city i

% Each city is visited exactly once, and forms a single tour
constraint all_different(succ);
constraint all_different(pred);

% Link pred and succ
constraint forall(i in Cities) (
    pred[succ[i]] = i
);

% No self-loops
constraint forall(i in Cities) (
    succ[i] != i
);

% Subtour elimination using circuit constraint
constraint circuit(succ);

% Compute the total travel distance
var int: travel_distance = sum(i in Cities)(dist[i, succ[i]]);

solve minimize travel_distance;

output [
    "{",
    "\"travel_distance\": ", show(travel_distance),
    "}"
];
