% Dreadsbury Mansion Murder Mystery

% Input data
set of int: People = 1..3;
array[People] of string: names = ["Agatha herself", "the butler", "Charles"];

% Decision variable: killer is the index of the killer
var People: killer;

% Each person can hate another person (including themselves)
array[People, People] of var bool: hates;

% Each person can be richer than another person (strictly richer)
array[People, People] of var bool: richer;

% 1. The killer killed Agatha (person 1), and the killer lives in the mansion
constraint killer in People;

% 2. The killer hates the victim (Agatha)
constraint hates[killer, 1];

% 3. The killer is no richer than the victim (not strictly richer)
constraint not richer[killer, 1];

% 4. Charles hates no one that Agatha hates
constraint forall(p in People where hates[1, p]) (
    not hates[3, p]
);

% 5. Agatha hates everybody except the butler
constraint hates[1, 1]; % Agatha hates herself
constraint not hates[1, 2]; % Agatha does not hate the butler
constraint hates[1, 3]; % Agatha hates Charles

% 6. The butler hates everyone not richer than Agatha
constraint forall(p in People where not richer[p, 1]) (
    hates[2, p]
);

% 7. The butler hates everyone whom Agatha hates
constraint forall(p in People where hates[1, p]) (
    hates[2, p]
);

% 8. No one hates everyone
constraint forall(p in People) (
    sum([hates[p, q] | q in People]) <= 2
);

% 9. No one is richer than themselves
constraint forall(p in People) (
    not richer[p, p]
);

% 10. Richer is antisymmetric: if p is richer than q, then q is not richer than p
constraint forall(p, q in People where p != q) (
    richer[p, q] -> not richer[q, p]
);

% 11. Richer is transitive: if p > q and q > r then p > r
constraint forall(p, q, r in People where p != q /\ q != r /\ p != r) (
    (richer[p, q] /\ richer[q, r]) -> richer[p, r]
);

solve satisfy;

output [
    "{",
    "\"killer\": ", show(killer),
    "}"
];
```

