% Wolf, Goat, and Cabbage River Crossing Problem

% Input data
int: stage = 8; % Number of stages (including initial and final)

% Entities: 1=destination shore, 0=starting shore
set of int: S = 1..stage;
enum ITEMS = {wolf, goat, cabbage, boat};

% Decision variables: position of each item at each stage
array[S, ITEMS] of var 0..1: pos;

% Initial state: all on starting shore
constraint forall(i in ITEMS)(pos[1, i] = 0);

% Final state: all on destination shore
constraint forall(i in ITEMS)(pos[stage, i] = 1);

% At each stage, only the farmer (boat) can move, possibly with one item
% The move must be valid: only the boat and at most one other item can change position
