% Include global constraints
include "globals.mzn";

% Input data
int: n_slots = 9; % Number of slots on a template
int: n_templates = 2; % Number of templates
int: n_var = 7; % Number of different variations
array[1..n_var] of int: demand = [250, 255, 260, 500, 500, 800, 1100];

% Decision variables

% layout[t, s]: which variation is assigned to slot s of template t (0 means empty slot)
array[1..n_templates, 1..n_slots] of var 0..n_var: layout;

% For each template, how many sheets are printed
array[1..n_templates] of var 0..max(demand): sheets;

% For each template and variation, how many times that variation appears on the template
array[1..n_templates, 1..n_var] of var 0..n_slots: var_count;

% For each variation, total number of items produced
array[1..n_var] of var int: produced;

% Constraints

% 1. For each template, count how many times each variation appears
constraint
  forall(t in 1..n_templates, v in 1..n_var) (
    var_count[t, v] = count([layout[t, s] | s in 1..n_slots], v)
  );

% 2. For each template, all slots must be filled with a variation (no empty slots)
constraint
  forall(t in 1..n_templates, s in 1..n_slots) (
    layout[t, s] > 0
  );

% 3. For each variation, total produced must be at least the demand
constraint
  forall(v in 1..n_var) (
    produced[v] = sum(t in 1..n_templates)(var_count[t, v] * sheets[t])
    /\ produced[v] >= demand[v]
  );

% 4. At least one slot per template must be assigned to each variation that appears on that template
% (already enforced by var_count and layout)

% 5. No slot can have a variation index outside 1..n_var (already enforced by domain)

% 6. Minimize total number of sheets printed
var int: production = sum(t in 1..n_templates)(sheets[t]);

solve minimize production;

output [
    "{",
    "\"production\": " ++ show(production) ++ ", ",
    "\"layout\": [" ++
        join(", ", [
            "[" ++ join(", ", [show(layout[t, s]) | s in 1..n_slots]) ++ "]"
            | t in 1..n_templates
        ]) ++
    "]",
    "}"
];
