% Low Autocorrelation Binary Sequences (LABS) Problem
% Given n, find a sequence of +1/-1 minimizing the sum of squared autocorrelations

include "globals.mzn";

% Input data
int: n = 10;

% Decision variables: sequence of +1/-1
array[0..n-1] of var {-1,1}: sequence;

% Autocorrelation variables for k = 1..n-1
array[1..n-1] of var int: C;

% Compute autocorrelations with periodic (cyclic) boundary conditions
constraint
  forall(k in 1..n-1) (
    C[k] = sum(i in 0..n-1) (sequence[i] * sequence[(i+k) mod n])
  );

% Energy: sum of squares of autocorrelations
var int: E = sum(k in 1..n-1)(C[k]*C[k]);

solve minimize E;

output [
    "{",
    "\"sequence\": [" ++ join(",", [show(sequence[i]) | i in 0..n-1]) ++ "],",
    "\"E\": " ++ show(E),
    "}"
];
```

