% Vessel Loading Problem

include "globals.mzn";

% ----------------------
% Input Data
% ----------------------
int: deck_width = 5;
int: deck_length = 5;
int: n_containers = 3;
array[1..n_containers] of int: width = [5, 2, 3];
array[1..n_containers] of int: length = [1, 4, 4];
array[1..n_containers] of int: classes = [1, 1, 1];
int: n_classes = 1; % Only class 1 is present
array[1..n_classes, 1..n_classes] of int: separation = 
    array2d(1..n_classes, 1..n_classes, [0, 0]);

% ----------------------
% Decision Variables
% ----------------------
% (x, y) is the bottom-left corner of the container
array[1..n_containers] of var 0..deck_width: x;
array[1..n_containers] of var 0..deck_length: y;

% Derived variables for output
array[1..n_containers] of var 0..deck_width: left;
array[1..n_containers] of var 0..deck_width: right;
array[1..n_containers] of var 0..deck_length: bottom;
array[1..n_containers] of var 0..deck_length: top;

constraint
    forall(i in 1..n_containers) (
        left[i] = x[i] /\
        right[i] = x[i] + width[i] /\
        bottom[i] = y[i] /\
        top[i] = y[i] + length[i]
    );

% ----------------------
% Constraints
% ----------------------

% 1. Containers must be within the deck
constraint
    forall(i in 1..n_containers) (
        x[i] >= 0 /\
        y[i] >= 0 /\
        x[i] + width[i] <= deck_width /\
        y[i] + length[i] <= deck_length
    );

% 2. No overlap between containers
constraint
    forall(i, j in 1..n_containers where i < j) (
        (x[i] + width[i] <= x[j]) \/
        (x[j] + width[j] <= x[i]) \/
        (y[i] + length[i] <= y[j]) \/
        (y[j] + length[j] <= y[i])
    );

% 3. Separation constraints (not needed here, but included for completeness)
constraint
    forall(i, j in 1..n_containers where i < j) (
        let {
            int: sep = separation[classes[i], classes[j]]
        } in
            sep = 0 \/ % If sep=0, no extra constraint
            (x[i] + width[i] + sep <= x[j] \/
             x[j] + width[j] + sep <= x[i] \/
             y[i] + length[i] + sep <= y[j] \/
             y[j] + length[j] + sep <= y[i])
    );

% 4. Loading sequence constraints
% Each container (except the first) must touch a wall or another container to the north and to the west
% Assume loading order is 1,2,3
constraint
    forall(i in 2..n_containers) (
        % Touches north: top[i] = deck_length OR exists j < i: top[i] = bottom[j] /\ overlap in x
        (
            top[i] = deck_length \/
            exists(j in 1..i-1) (
                bottom[j] = top[i] /\
                not (right[i] <= left[j] \/ right[j] <= left[i])
            )
        )
        /\
        % Touches west: left[i] = 0 OR exists j < i: right[j] = left[i] /\ overlap in y
        (
            left[i] = 0 \/
            exists(j in 1..i-1) (
                right[j] = left[i] /\
                not (top[i] <= bottom[j] \/ top[j] <= bottom[i])
            )
        )
    );

% ----------------------
% Solve
% ----------------------
solve satisfy;

% ----------------------
% Output
% ----------------------
output [
    "{",
    "\"left\": [" ++ join(",", [show(left[i]) | i in 1..n_containers]) ++ "],",
    "\"right\": [" ++ join(",", [show(right[i]) | i in 1..n_containers]) ++ "],",
    "\"top\": [" ++ join(",", [show(top[i]) | i in 1..n_containers]) ++ "],",
    "\"bottom\": [" ++ join(",", [show(bottom[i]) | i in 1..n_containers]) ++ "]",
    "}"
];
