% Social Golfers Problem (SGP) instance
% Input data
int: n_weeks = 4;      % Number of weeks
int: n_groups = 3;     % Number of groups per week
int: group_size = 3;   % Number of golfers per group

int: n_golfers = n_groups * group_size;

set of int: GOLFERS = 1..n_golfers;
set of int: WEEKS = 1..n_weeks;
set of int: GROUPS = 1..n_groups;
set of int: POS = 1..group_size;

% Decision variables:
% assign[w,g,p] = golfer assigned to week w, group g, position p
array[WEEKS, GROUPS, POS] of var GOLFERS: assign;

% Each golfer plays exactly once per week
constraint
  forall(w in WEEKS)(
    alldifferent([assign[w,g,p] | g in GROUPS, p in POS])
  );

% Each group has unique golfers
constraint
  forall(w in WEEKS, g in GROUPS)(
    alldifferent([assign[w,g,p] | p in POS])
  );

% No pair of golfers plays together in the same group more than once
% For each pair of golfers, count the number of weeks they are together in a group, must be <= 1
constraint
  forall(g1 in GOLFERS, g2 in GOLFERS where g1 < g2) (
    sum([
      exists(w in WEEKS, g in GROUPS)(
        exists(p1 in POS, p2 in POS where p1 != p2)(
          assign[w,g,p1] = g1 /\ assign[w,g,p2] = g2
        )
      )
    ]) <= 1
  );

% Symmetry breaking: golfer 1 is always in group 1, position 1
constraint
  forall(w in WEEKS)(
    assign[w,1,1] = 1
  );

solve satisfy;

output [
  "{",
  "\"assign\": [",
    join(",\n", [
      "[" ++
        join(",", [
          "[" ++ join(",", [show(assign[w,g,p]) | p in POS]) ++ "]"
          | g in GROUPS
        ]) ++ "]"
      | w in WEEKS
    ]),
  "]",
  "}"
];
