% Include global constraints
include "globals.mzn";

% Input data
int: rows = 8;
int: cols = 13;
int: row_rule_len = 2;
int: col_rule_len = 2;
array[1..rows, 1..row_rule_len] of int: row_rules = 
    [| 0, 1
     | 0, 2
     | 4, 4
     | 0,12
     | 0, 8
     | 0, 9
     | 3, 4
     | 2, 2 |];
array[1..cols, 1..col_rule_len] of int: col_rules = 
    [| 0, 2
     | 2, 1
     | 3, 2
     | 0, 6
     | 1, 4
     | 0, 3
     | 0, 4
     | 0, 4
     | 0, 4
     | 0, 5
     | 0, 4
     | 1, 3
     | 0, 2 |];

% Decision variables: 1 = filled, 0 = empty
array[1..rows, 1..cols] of var 0..1: board;

% Helper function to extract nonzero blocks from a rule
function array[int] of int: get_blocks(array[int] of int: rule) =
    [b | b in rule where b > 0];

% Constraint for a line (row or column) to match its rule
predicate line_matches_rule(array[int] of var 0..1: line, array[int] of int: rule) =
    let {
        array[int] of int: blocks = get_blocks(rule),
        int: num_blocks = length(blocks),
        int: n = length(line),
        % The start positions of each block
        array[1..num_blocks] of var 1..n: starts
    } in
        % Each block must fit in the line
        forall(i in 1..num_blocks) (
            starts[i] + blocks[i] - 1 <= n
        )
        /\
        % Blocks must not overlap and must be separated by at least one empty cell
        forall(i in 1..num_blocks-1) (
            starts[i+1] > starts[i] + blocks[i]
        )
        /\
        % The cells corresponding to blocks are filled, others are empty
        forall(i in 1..n) (
            let {
                set of int: covering_blocks = {j | j in 1..num_blocks where starts[j] <= i /\ i < starts[j] + blocks[j]}
            } in
                (if card(covering_blocks) > 0 then line[i] = 1 else line[i] = 0 endif)
        );

% Row constraints
constraint
    forall(r in 1..rows) (
        line_matches_rule([board[r, c] | c in 1..cols], row_rules[r, 1..row_rule_len])
    );

% Column constraints
constraint
    forall(c in 1..cols) (
        line_matches_rule([board[r, c] | r in 1..rows], col_rules[c, 1..col_rule_len])
    );

solve satisfy;

output [
    "{",
    "\"board\": [",
    join(",", [ "[" ++ join(",", [show(board[r, c]) | c in 1..cols]) ++ "]" | r in 1..rows ]),
    "]",
    "}"
];
