```minizinc
% Progressive Party Problem (PPP)
% Minimize the number of host boats and schedule visits

include "globals.mzn";

% Input data
int: n_boats = 5;
int: n_periods = 4;
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

% Decision variables
array[1..n_boats] of var bool: is_host; % is_host[b] = 1 if boat b is a host

% visits[g,h,p] = 1 if guest boat g visits host h at period p
array[1..n_boats, 1..n_boats, 1..n_periods] of var bool: visits;

% Constraints

% 1. A boat cannot visit itself
constraint
  forall(g in 1..n_boats, p in 1..n_periods) (
    visits[g,g,p] = false
  );

% 2. Only host boats can be visited
constraint
  forall(g in 1..n_boats, h in 1..n_boats, p in 1..n_periods where g != h) (
    visits[g,h,p] <= is_host[h]
  );

% 3. Host crews stay on their own boat, guests must visit a host each period
%    (Host boats do not visit anyone)
constraint
  forall(h in 1..n_boats, p in 1..n_periods) (
    % Host boats do not visit anyone
    is_host[h] = 1 -> forall(h2 in 1..n_boats where h2 != h) (visits[h,h2,p] = false)
  );

% 4. Each guest boat visits exactly one host per period (if not a host)
constraint
  forall(g in 1..n_boats) (
    is_host[g] = 0 ->
      forall(p in 1..n_periods) (
        sum([visits[g,h,p] | h in 1..n_boats where h != g]) = 1
      )
  );

% 5. Host boats do not visit anyone
constraint
  forall(h in 1..n_boats, p in 1..n_periods) (
    is_host[h] = 1 -> sum([visits[h,h2,p] | h2 in 1..n_boats where h2 != h]) = 0
  );

% 6. Each guest boat never visits the same host twice
constraint
  forall(g in 1..n_boats, h in 1..n_boats where g != h) (
    sum([visits[g,h,p] | p in 1..n_periods]) <= 1
  );

% 7. Guest crews cannot meet more than once
%    For each pair of guest boats, count the number of periods they are on the same host
constraint
  forall(g1 in 1..n_boats, g2 in 1..n_boats where g1 < g2) (
    sum([
      bool2int(
        exists(h in 1..n_boats) (
          exists(p in 1..n_periods) (
            visits[g1,h,p] = 1 /\ visits[g2,h,p] = 1
          )
        )
      )
    ]) <= 1
  );

% 8. Capacity constraints: For each host, in each period, total people on board <= capacity
constraint
  forall(h in 1..n_boats, p in 1..n_periods) (
    sum([crew_size[g] * visits[g,h,p] | g in 1..n_boats where g != h]) + (is_host[h] * crew_size[h]) <= capacity[h]
  );

% 9. A boat cannot be both a host and a guest in the same period
constraint
  forall(b in 1..n_boats, p in 1..n_periods) (
    is_host[b] = 1 -> sum([visits[b,h,p] | h in 1..n_boats where h != b]) = 0
  );

% 10. Guest boats do not stay on their own boat
constraint
  forall(g in 1..n_boats, p in 1..n_periods) (
    visits[g,g,p] = 0
  );

% Objective: Minimize the number of host boats
solve minimize sum([is_host[b] | b in 1..n_boats]);

% Output: visits[g,h,p] and is_host
output [
  "{",
  "\"visits\": [",
    join(",", [
      "[" ++
        join(",", [
          "[" ++
            join(",", [
              show(fix(visits[g,h,p]))
              | p in 1..n_periods
            ]) ++ "]"
          | h in 1..n_boats
        ]) ++ "]"
      | g in 1..n_boats
    ]),
  "],",
  "\"is_host\": [" ++ join(",", [show(fix(is_host[b])) | b in 1..n_boats]) ++ "]",
  "}"
];
```

