include "globals.mzn";

% Input data
int: n = 8; % Number of words to find
int: word_len = 8;

% Alphabet: A=1, C=2, G=3, T=4
set of int: Alphabet = 1..4;

% Mapping for Watson-Crick complement:
% A <-> T, C <-> G
array[Alphabet] of int: complement = [4,3,2,1];

% Decision variables: words[w, p] is the symbol at position p in word w
array[1..n, 1..word_len] of var Alphabet: words;

% Each word must have exactly 4 symbols from {C,G} (i.e., 2 or 3)
constraint
  forall(w in 1..n) (
    count([words[w,p] | p in 1..word_len], 2) + count([words[w,p] | p in 1..word_len], 3) = 4
  );

% Each pair of distinct words must differ in at least 4 positions (Hamming distance >= 4)
constraint
  forall(w1 in 1..n, w2 in w1+1..n) (
    sum([bool2int(words[w1,p] != words[w2,p]) | p in 1..word_len]) >= 4
  );

% For all pairs (x, y), x^R and y^C differ in at least 4 positions
constraint
  forall(x in 1..n, y in 1..n) (
    sum([
      bool2int(
        words[x, word_len - p + 1] != complement[words[y, p]]
      ) | p in 1..word_len
    ]) >= 4
  );

% Optional: symmetry breaking (lex order)
constraint
  forall(w in 1..n-1) (
    lex_lesseq([words[w,p] | p in 1..word_len], [words[w+1,p] | p in 1..word_len])
  );

solve satisfy;

% Output: print the set of words as a list of lists of integers (1=A, 2=C, 3=G, 4=T)
output [
  "{",
  "\"words\": [",
  join(", ", [
    "[" ++ join(",", [show(words[w,p]) | p in 1..word_len]) ++ "]"
    | w in 1..n
  ]),
