% Steiner Triple System of order n=9
% Find a set of n*(n-1)/6 triples of {1..n} such that every pair appears in exactly one triple

include "globals.mzn";

% Input data
int: n = 9;
int: num_triples = n * (n - 1) div 6; % Number of triples

set of int: ELEMENTS = 1..n;
set of int: TRIPLES = 1..num_triples;

% Decision variables: triples[t, 1..3] is the t-th triple (sorted)
array[TRIPLES, 1..3] of var ELEMENTS: triples;

% Each triple contains 3 distinct elements, sorted to break symmetry
constraint
  forall(t in TRIPLES) (
    triples[t,1] < triples[t,2] /\
    triples[t,2] < triples[t,3]
  );

% No two triples are identical (redundant due to sorting, but explicit)
constraint
  forall(t1, t2 in TRIPLES where t1 < t2) (
    exists(i in 1..3, j in 1..3) (
      triples[t1,i] != triples[t2,j]
    )
  );

% Every pair of elements appears in exactly one triple
array[1..n, 1..n] of var 0..1: pair_in_triple;

constraint
  forall(i, j in 1..n where i < j) (
    let {
      % For each triple, does it contain both i and j?
      array[TRIPLES] of var bool: in_triple = [exists(k1, k2 in 1..3 where k1 < k2) (
        (triples[t,k1] == i /\ triples[t,k2] == j) \/ (triples[t,k1] == j /\ triples[t,k2] == i)
      ) | t in TRIPLES]
    } in
      sum(t in TRIPLES)(bool2int(in_triple[t])) == 1
  );

% Optional: symmetry breaking - first triple is smallest lexicographically
constraint
  triples[1,1] == 1 /\ triples[1,2] == 2 /\ triples[1,3] == 3;

solve satisfy;

output [
  "{",
  "\"sets\": [",
    join(",", [
      "[" ++ join(",", [show(triples[t,i]) | i in 1..3]) ++ "]"
      | t in TRIPLES
    ]),
  "]",
  "}"
];
