% Number Partitioning Problem for n = 12

include "globals.mzn";

int: n = 12;
set of int: NUMS = 1..n;
int: half_n = n div 2;

% Decision variables: assign[i] = 1 if i in A, 0 if i in B
array[NUMS] of var 0..1: assign;

% Sets A and B
array[1..half_n] of var NUMS: A;
array[1..half_n] of var NUMS: B;

% Constraints

% Each number assigned to exactly one set
constraint sum(i in NUMS)(assign[i]) = half_n;

% Build sets A and B from assign
constraint
    forall(i in 1..half_n) (
        exists(j in NUMS) (
            assign[j] = 1 /\ A[i] = j
        )
    )
    /\
    forall(i in 1..half_n) (
        exists(j in NUMS) (
            assign[j] = 0 /\ B[i] = j
        )
    );

% All elements in A are distinct, and all in B are distinct
constraint all_different(A);
constraint all_different(B);

% A and B are disjoint and cover all numbers
constraint
    forall(i in 1..half_n, j in 1..half_n) (
        A[i] != B[j]
    );

% Sums of A and B are equal
constraint sum(i in 1..half_n)(A[i]) = sum(i in 1..half_n)(B[i]);

% Sums of squares of A and B are equal
constraint sum(i in 1..half_n)(A[i]*A[i]) = sum(i in 1..half_n)(B[i]*B[i]);

% For symmetry breaking: smallest element of A is less than smallest of B
constraint min(A) < min(B);

solve satisfy;

output [
    "{",
    "\"A\": [" ++ join(",", [show(A[i]) | i in 1..half_n]) ++ "],",
    "\"B\": [" ++ join(",", [show(B[i]) | i in 1..half_n]) ++ "]",
    "}"
];
