% Diamond-free Degree Sequences for N=10

include "globals.mzn";

int: N = 10;

% Decision variables
array[1..N, 1..N] of var 0..1: matrix; % adjacency matrix
array[1..N] of var 1..N-1: d;          % degree sequence (no isolated vertices, max degree N-1)

% Constraints

% 1. No loops
constraint forall(i in 1..N)(matrix[i,i] = 0);

% 2. Symmetry (undirected graph)
constraint forall(i, j in 1..N where i < j)(matrix[i,j] = matrix[j,i]);

% 3. Degree sequence: d[i] = sum of row i
constraint forall(i in 1..N)(
    d[i] = sum(j in 1..N)(matrix[i,j])
);

% 4. Degree sequence is non-increasing
constraint forall(i in 1..N-1)(
    d[i] >= d[i+1]
);

% 5. Each degree is > 0 and divisible by 3
constraint forall(i in 1..N)(
    d[i] mod 3 = 0
);

% 6. Sum of degrees is divisible by 12
constraint sum(i in 1..N)(d[i]) mod 12 = 0;

% 7. Diamond-free: For every set of 4 vertices, at most 4 edges among them
set of int: VERTICES = 1..N;
array[1..4] of int: idxs; % helper for combinations

% Helper: all 4-combinations of vertices
function array[int] of array[int] of int: all_4_combinations(int: n) =
    let {
        int: num = binomial(n,4),
        array[1..num,1..4] of int: combs = 
            array1d(1..num*4, [i1,i2,i3,i4 | i1 in 1..n-3, i2 in i1+1..n-2, i3 in i2+1..n-1, i4 in i3+1..n])
    } in
        combs;

array[1..binomial(N,4),1..4] of int: combs = all_4_combinations(N);

constraint
    forall(c in 1..binomial(N,4)) (
        let {
            int: a = combs[c,1],
            int: b = combs[c,2],
            int: c2 = combs[c,3],
            int: d2 = combs[c,4]
        } in
            % Count the edges among these 4 vertices
            (matrix[a,b] + matrix[a,c2] + matrix[a,d2] +
             matrix[b,c2] + matrix[b,d2] +
             matrix[c2,d2]) <= 4
    );

% 8. Simple graph: no multiple edges (already enforced by 0/1 matrix)

% 9. Break symmetry: only output lex-leader for degree sequence
constraint
    lex_leq([d[i] | i in 1..N], [d[i] | i in 1..N]);

solve satisfy;

output [
    "{",
    "\"matrix\": [",
    join(",", [
        "[" ++ join(",", [show(matrix[i,j]) | j in 1..N]) ++ "]"
        | i in 1..N
    ]),
    "]",
    "}"
];
```

