% Graceful Graph Labelling Problem

include "globals.mzn";

% Input data
int: m = 16; % Number of edges
int: n = 8;  % Number of nodes
array[1..m, 1..2] of int: graph = 
    [| 0, 1 | 0, 2 | 0, 3 | 1, 2 | 1, 3 | 2, 3 |
       4, 5 | 4, 6 | 4, 7 | 5, 6 | 5, 7 | 6, 7 |
       0, 4 | 1, 5 | 2, 6 | 3, 7 |];

% The node indices in the input are 0-based, but MiniZinc arrays are 1-based.
% We'll use 1-based indexing for node variables, and adjust the graph accordingly.

% Decision variables
array[1..n] of var 0..m: nodes;   % Node labels: unique in 0..m
array[1..m] of var 1..m: edges;   % Edge labels: unique in 1..m (no zero)

% Constraints

% Node labels are all different
constraint all_different(nodes);

% Edge labels are all different
constraint all_different(edges);

% For each edge, set the edge label to the absolute difference of its node labels
constraint
    forall(e in 1..m) (
        let {
            % Convert 0-based node indices to 1-based for MiniZinc arrays
            var int: u = nodes[graph[e,1]+1],
            var int: v = nodes[graph[e,2]+1]
        } in
            edges[e] = abs(u - v)
    );

% Edge labels must be in 1..m (already set by domain)
% Node labels must be in 0..m (already set by domain)

solve satisfy;

output [
    "{",
    "\"nodes\": [" ++ join(",", [show(nodes[i]) | i in 1..n]) ++ "],",
    "\"edges\": [" ++ join(",", [show(edges[i]) | i in 1..m]) ++ "]",
    "}"
];
```

