% N-Queens Problem for n = 10

include "globals.mzn";

% Input data
int: n = 10;

% Decision Variables
% queens[i] = the column of the queen in row i (1-based indexing)
array[1..n] of var 1..n: queens;

% Constraints

% 1. All queens must be in different columns
constraint
    all_different(queens);

% 2. All queens must be in different major diagonals (row - col)
constraint
    all_different([i - queens[i] | i in 1..n]);

% 3. All queens must be in different minor diagonals (row + col)
constraint
    all_different([i + queens[i] | i in 1..n]);

solve satisfy;

output [
    "{",
    "\"queens\": [" ++ join(",", [show(queens[i]) | i in 1..n]) ++ "]",
    "}"
];
