% Include the global constraints library
include "globals.mzn";

% Input data
int: n = 8;

% Decision variables: costas[i] is the column position of the mark in row i (1-based)
array[1..n] of var 1..n: costas;

% The main permutation constraint: one mark per row and column
constraint
    all_different(costas);

% For each l in 1..n-1, the differences between costas[i] and costas[i+l] must be all different
% We build the difference triangle
array[1..n-1, 1..n-1] of var -n+1..n-1: diff_triangle;

constraint
    forall(l in 1..n-1) (
        let {
            set of int: idxs = 1..n-l
        } in
            % Fill the difference triangle for this l
            forall(i in idxs) (
                diff_triangle[l, i] = costas[i] - costas[i+l]
            ) /\
            % All differences for this l must be different
            all_different([diff_triangle[l, i] | i in idxs])
    );

solve satisfy;

output [
    "{",
    "\"costas\": [" ++ join(",", [show(costas[i]) | i in 1..n]) ++ "]",
    "}"
];
