% 2cc Hadamard Matrix Legendre Pairs CSP for l = 9

include "globals.mzn";

% Input parameter
int: l = 9;
int: m = (l - 1) div 2;

% Decision variables: a_1..a_l, b_1..b_l in {-1, +1}
array[1..l] of var {-1,1}: a;
array[1..l] of var {-1,1}: b;

% Helper function: periodic index
function int: pidx(int: i) = if i mod l = 0 then l else i mod l endif;

% Constraints

% m quadratic constraints: PAF(A,s) + PAF(B,s) = -2 for s = 1..m
constraint
  forall(s in 1..m) (
    sum(i in 1..l) (a[i] * a[pidx(i+s)]) +
    sum(i in 1..l) (b[i] * b[pidx(i+s)])
    = -2
  );

% Linear constraints: sum(a) = 1, sum(b) = 1
constraint sum(i in 1..l)(a[i]) = 1;
constraint sum(i in 1..l)(b[i]) = 1;

solve satisfy;

output [
  "{",
  "\"a\": [" ++ join(",", [show(a[i]) | i in 1..l]) ++ "], ",
  "\"b\": [" ++ join(",", [show(b[i]) | i in 1..l]) ++ "]",
  "}"
];
