% The product of the ages is 36
% The sum of the ages is ambiguous (i.e., there are at least two different triples with the same sum)
% There is a unique oldest son (i.e., one age is strictly greater than the others)

include "globals.mzn";

% The ages must be positive integers
set of int: Ages = 1..36;

% Decision variables: the ages of the three sons
var Ages: A1; % oldest
var Ages: A2;
var Ages: A3;

% Enforce ordering: A1 >= A2 >= A3
constraint A1 >= A2 /\ A2 >= A3;

% The product of their ages is 36
constraint A1 * A2 * A3 == 36;

% The sum of their ages
var int: S = A1 + A2 + A3;

% Find all possible age triples (ordered non-increasingly) with product 36
array[int] of var int: all_A1;
array[int] of var int: all_A2;
array[int] of var int: all_A3;
array[int] of var int: all_S;

% We enumerate all possible ordered triples (A1',A2',A3') with product 36
% and store their sums
set of int: I = 1..100; % upper bound, more than enough for all possible triples

% We'll collect all possible (A1',A2',A3') with product 36 and A1' >= A2' >= A3'
% and their sums
int: n_triples = 
    sum([bool2int(a1*a2*a3 == 36 /\ a1 >= a2 /\ a2 >= a3) | a1 in Ages, a2 in Ages, a3 in Ages]);

array[1..n_triples] of int: poss_A1 = [a1 | a1 in Ages, a2 in Ages, a3 in Ages where a1*a2*a3 == 36 /\ a1 >= a2 /\ a2 >= a3];
array[1..n_triples] of int: poss_A2 = [a2 | a1 in Ages, a2 in Ages, a3 in Ages where a1*a2*a3 == 36 /\ a1 >= a2 /\ a2 >= a3];
array[1..n_triples] of int: poss_A3 = [a3 | a1 in Ages, a2 in Ages, a3 in Ages where a1*a2*a3 == 36 /\ a1 >= a2 /\ a2 >= a3];
array[1..n_triples] of int: poss_S  = [a1+a2+a3 | a1 in Ages, a2 in Ages, a3 in Ages where a1*a2*a3 == 36 /\ a1 >= a2 /\ a2 >= a3];

% The sum S must be ambiguous: there must be at least two different triples with the same sum S
% i.e., S occurs at least twice in poss_S
constraint
    exists(i, j in 1..n_triples where i < j)(poss_S[i] == poss_S[j] /\ poss_S[i] == S);

% The "oldest son" clue: there is a unique oldest son, i.e., A1 > A2
constraint A1 > A2;

solve satisfy;

output [
    "{",
    join(",", [
        "\"A1\": " ++ show(A1),
        "\"A2\": " ++ show(A2),
        "\"A3\": " ++ show(A3)
    ]),
    "}"
];
