% Include necessary library
include "globals.mzn";

% Decision variables: my age (m) and husband's age (h)
var 1..120: m;
var 1..120: h;

% There are 4 operations: +2, /8, -3, *7
% We represent the sequence of operations as a permutation of [1,2,3,4]
% 1: +2, 2: /8, 3: -3, 4: *7

array[1..4] of int: ops = [1,2,3,4];

% Permutations for the order of operations
array[1..4] of var 1..4: perm1; % order for m -> h
array[1..4] of var 1..4: perm2; % order for h -> m

constraint all_different(perm1);
constraint all_different(perm2);

% Helper function to apply an operation
function var int: apply_op(var int: x, int: op) =
    if op = 1 then x + 2
    else if op = 2 then x div 8
    else if op = 3 then x - 3
    else if op = 4 then x * 7
    else x endif endif endif endif;

% Apply the sequence of operations for m -> h
var int: step1_1 = apply_op(m, perm1[1]);
var int: step1_2 = apply_op(step1_1, perm1[2]);
var int: step1_3 = apply_op(step1_2, perm1[3]);
var int: result1 = apply_op(step1_3, perm1[4]);

% Apply the sequence of operations for h -> m
var int: step2_1 = apply_op(h, perm2[1]);
var int: step2_2 = apply_op(step2_1, perm2[2]);
var int: step2_3 = apply_op(step2_2, perm2[3]);
var int: result2 = apply_op(step2_3, perm2[4]);

% The result of applying the operations in some order to m is h
constraint result1 = h;
% The result of applying the operations in some (different) order to h is m
constraint result2 = m;

% The two orders must be different
constraint exists(i in 1..4)(perm1[i] != perm2[i]);

% Ages must be positive integers
constraint m > 0 /\ h > 0;

solve satisfy;

output [
    "{",
    "\"m\": ", show(m), ", ",
    "\"h\": ", show(h),
    "}"
];
```

