% Include the global constraints library
include "globals.mzn";

% Number of friends
int: n = 4;

% Friend indices
% 0: Debra, 1: Janet, 2: Hugh, 3: Rick

% Surnames
enum Surname = {baxter, lemon, malone, fleet};

% Allergies
enum Allergy = {eggs, mold, nuts, ragweed};

% Decision variables:
% surname[i]: the surname of friend i
array[0..n-1] of var Surname: surname;
% allergy[i]: the allergy of friend i
array[0..n-1] of var Allergy: allergy;

% Each surname and allergy is assigned exactly once
constraint all_different([surname[i] | i in 0..n-1]);
constraint all_different([allergy[i] | i in 0..n-1]);

% Rick is not allergic to mold
constraint allergy[3] != mold;

% Baxter is allergic to eggs
% Find the index of Baxter, and set their allergy to eggs
constraint forall(i in 0..n-1) (
    (surname[i] == baxter) <-> (allergy[i] == eggs)
);

% Hugh is neither surnamed Lemon nor Fleet
constraint surname[2] != lemon /\ surname[2] != fleet;

% Debra is allergic to ragweed
constraint allergy[0] == ragweed;

% Janet (who isn't Lemon) is neither allergic to eggs nor to mold
constraint surname[1] != lemon;
constraint allergy[1] != eggs /\ allergy[1] != mold;

solve satisfy;

output [
    "{",
    "\"eggs\": " ++ show([if allergy[i] == eggs then 1 else 0 endif | i in 0..n-1]) ++ ",",
    "\"mold\": " ++ show([if allergy[i] == mold then 1 else 0 endif | i in 0..n-1]) ++ ",",
    "\"nuts\": " ++ show([if allergy[i] == nuts then 1 else 0 endif | i in 0..n-1]) ++ ",",
    "\"ragweed\": " ++ show([if allergy[i] == ragweed then 1 else 0 endif | i in 0..n-1]) ++ ",",
    "\"baxter\": " ++ show([if surname[i] == baxter then 1 else 0 endif | i in 0..n-1]) ++ ",",
    "\"lemon\": " ++ show([if surname[i] == lemon then 1 else 0 endif | i in 0..n-1]) ++ ",",
    "\"malone\": " ++ show([if surname[i] == malone then 1 else 0 endif | i in 0..n-1]) ++ ",",
    "\"fleet\": " ++ show([if surname[i] == fleet then 1 else 0 endif | i in 0..n-1]),
    "}"
];
