constraint all_different([store_at_pos[i] | i in 1..n]);

% 1. Harriet bought fuchsia flats at Heels in a Handcart.
constraint
    exists(i in 1..n) (
        shoe_at_pos[i] = fuchsiaflats /\
        store_at_pos[i] = heelsinahandcart
    );

% 2. The store she visited just after buying her purple pumps was not Tootsies.
% That is, for some i in 1..n-1, shoe_at_pos[i]=purplepumps, store_at_pos[i+1] != tootsies
constraint
    forall(i in 1..n-1) (
        (shoe_at_pos[i] = purplepumps) -> (store_at_pos[i+1] != tootsies)
    );

% 3. The Foot Farm was Harriet's second stop.
constraint store_at_pos[2] = footfarm;

