% Objective: Minimize total cost
var int: total_cost = sum(t in 1..num_tasks, p in 1..num_people)(cost[t,p] * x[t,p]);

solve minimize total_cost;

% Output in JSON format
output [
    "{",
    "\"x\": [",
        join(",", [
            "[" ++ join(",", [show(x[t,p]) | p in 1..num_people]) ++ "]"
            | t in 1..num_tasks
        ]),
    "]",
    "}"
];
