% Number of bales
int: n = 5;

% The 10 pairwise sums, sorted
array[1..10] of int: pair_sums = [80, 82, 83, 84, 85, 86, 87, 88, 90, 91];

% Decision variables: the weights of the bales, sorted in increasing order
array[1..n] of var 1..100: bales;

% All bales must have different weights (since all pairwise sums are different)
constraint increasing(bales);

% Generate all pairs (i, j) with i < j
set of int: PAIRS = 1..n;
array[1..10] of var int: computed_sums;

% Map the 10 pairs to the computed_sums array
% The pairs in lex order: (1,2),(1,3),(1,4),(1,5),(2,3),(2,4),(2,5),(3,4),(3,5),(4,5)
constraint
    computed_sums[1] = bales[1] + bales[2] /\
    computed_sums[2] = bales[1] + bales[3] /\
    computed_sums[3] = bales[1] + bales[4] /\
    computed_sums[4] = bales[1] + bales[5] /\
    computed_sums[5] = bales[2] + bales[3] /\
    computed_sums[6] = bales[2] + bales[4] /\
    computed_sums[7] = bales[2] + bales[5] /\
    computed_sums[8] = bales[3] + bales[4] /\
    computed_sums[9] = bales[3] + bales[5] /\
    computed_sums[10] = bales[4] + bales[5];

% The multiset of computed_sums must match the given pair_sums
constraint
    global_cardinality_low_up(computed_sums, pair_sums, [1 | i in 1..10], [1 | i in 1..10]);

solve satisfy;

output [
    "{",
    "\"bales\": [" ++ join(",", [show(bales[i]) | i in 1..n]) ++ "]",
    "}"
