% For each guest, define the set of guests they are willing to sit next to
set of int: GUESTS = 0..5;
array[GUESTS] of set of int: allowed_neighbors = [
    {3,5},    % Andrew: Dave(3), Frank(5)
    {2,4},    % Betty: Cara(2), Erica(4)
    {1,5},    % Cara: Betty(1), Frank(5)
    {0,4},    % Dave: Andrew(0), Erica(4)
    {1,3},    % Erica: Betty(1), Dave(3)
    {0,2}     % Frank: Andrew(0), Cara(2)
];

% Decision variable: seating order
array[1..n] of var GUESTS: x;

% All guests must be seated exactly once
constraint all_different(x);

% For each pair of adjacent seats (including wrap-around), count conflicts
array[1..n] of var 0..1: conflict;

constraint
    forall(i in 1..n) (
        let {
            var int: left = x[i],
            var int: right = x[if i < n then i+1 else 1]
        } in
            % There is a conflict if left and right are not allowed neighbors
            conflict[i] = bool2int(not (right in allowed_neighbors[left]))
    );

% Objective: minimize total conflicts
var 0..n: total_conflict = sum(i in 1..n)(conflict[i]);

solve minimize total_conflict;

output [
    "{",
    "\"x\": [" ++ join(",", [show(x[i]) | i in 1..n]) ++ "]",
    "}"
];
