% Nontransitive dice for Rock-Paper-Scissors-Lizard-Spock
% Each die corresponds to one of the choices: Rock(1), Paper(2), Scissors(3), Lizard(4), Spock(5)
% Each die should "beat" two others and "lose" to two others, according to the relationships.

include "globals.mzn";

int: num_dice = 5;
int: faces = 6; % Number of faces per die (standard dice)
set of int: DICE = 1..num_dice;
set of int: FACE = 1..faces;

% The 'beats' relationships as (winner, loser) pairs
set of int: BEATS = 1..10;
array[BEATS, 1..2] of int: beats = 
[
    % winner, loser
    | 1, 3 % Rock crushes Scissors
    | 1, 4 % Rock crushes Lizard
    | 2, 1 % Paper covers Rock
    | 2, 5 % Paper disproves Spock
    | 3, 2 % Scissors cuts Paper
    | 3, 4 % Scissors decapitate Lizard
    | 4, 2 % Lizard eats Paper
    | 4, 5 % Lizard poisons Spock
    | 5, 1 % Spock vaporizes Rock
    | 5, 3 % Spock smashes Scissors
];

% Decision variables: dice[d, f] is the value of face f on die d
array[DICE, FACE] of var 1..15: dice;

% For each pair of dice (i, j), count the number of times die i beats die j
% win[i,j] = number of (f,g) such that dice[i,f] > dice[j,g]
array[DICE, DICE] of var 0..faces*faces: win;

% Compute win[i,j]
constraint
    forall(i in DICE, j in DICE) (
        win[i,j] = sum([bool2int(dice[i,f] > dice[j,g]) | f in FACE, g in FACE])
    );

% For each (winner, loser) in beats, winner should beat loser in more than half of the face-offs
constraint
    forall(b in BEATS) (
        win[beats[b,1], beats[b,2]] > (faces*faces) div 2
    );

% For the reverse, the loser should not beat the winner (i.e., win[loser,winner] < half)
constraint
    forall(b in BEATS) (
        win[beats[b,2], beats[b,1]] < (faces*faces) div 2
    );

% For all other pairs (not in beats), neither die should dominate the other
% That is, for pairs (i,j) not in beats or its reverse, win[i,j] = win[j,i]
constraint
    forall(i in DICE, j in DICE where i != j /\
        not exists(b in BEATS)( (beats[b,1]=i /\ beats[b,2]=j) \/ (beats[b,1]=j /\ beats[b,2]=i) )
    ) (
        win[i,j] = win[j,i]
    );

% Optional: symmetry breaking to reduce search space
constraint
    forall(d in DICE) (
        increasing([dice[d,f] | f in FACE])
    );
constraint
    increasing([dice[d,1] | d in DICE]);

solve satisfy;

output [
    "{",
    "\"dice\": [",
    join(",", [ "[" ++ join(",", [show(dice[d,f]) | f in FACE]) ++ "]" | d in DICE ]),
    "]",
    "}"
];
```

