% Bachet's weighing problem: Find four integer weights that sum to 40,
% and can weigh every integer from 1 to 40 pounds using a balance scale.

include "globals.mzn";

% Number of pieces
int: n = 4;

% The weights of the pieces, in non-decreasing order
array[1..n] of var 1..40: weights;

% The total weight must be 40
constraint sum(weights) = 40;

% Enforce non-decreasing order to break symmetry
constraint forall(i in 1..n-1)(weights[i] <= weights[i+1]);

% For each target weight from 1 to 40, we must be able to weigh it
% using the four pieces, each of which can be placed on the left pan (-1),
% not used (0), or right pan (+1).
set of int: CHOICES = {-1, 0, 1};

array[1..40, 1..n] of var CHOICES: assign;

% For each target weight t, the sum over i of assign[t,i]*weights[i] must be t
% (object is on right pan, so positive sum means right pan heavier)
constraint forall(t in 1..40)(
    exists(assign[t,1..n]) (
        sum(i in 1..n)(assign[t,i]*weights[i]) = t
    )
);

solve satisfy;

output [
    "{",
    "\"weights\": [" ++ join(",", [show(weights[i]) | i in 1..n]) ++ "]",
    "}"
];
```

