    array2d(1..12, 1..4, [
        letter_index(substr(words[w],i,i)) | w in 1..12, i in 1..4
    ]);

% There are 4 blocks (dice), each with 6 letters
int: num_blocks = 4;
int: faces_per_block = 6;

