% Minizinc model for optimal rack device placement to minimize total cable length

include "globals.mzn";

% Number of devices
int: n = 8;

% Device names for reference (A=1, ..., H=8)
set of int: Devices = 1..n;

% List of connections: (device1, device2, number_of_cables)
% Devices are mapped as: A=1, B=2, C=3, D=4, E=5, F=6, G=7, H=8
int: num_connections = 8;
array[1..num_connections, 1..3] of int: connections = 
[
    % device1, device2, cables
    1, 8, 1,   % A-H
    1, 5, 2,   % A-E
    2, 6, 4,   % B-F
    3, 7, 1,   % C-G
    3, 4, 1,   % C-D
    3, 5, 1,   % C-E
    4, 8, 3,   % D-H
    7, 8, 1    % G-H
];

% Decision variables: position[d] is the rack position (1..n) of device d
array[Devices] of var 1..n: position;

% All devices must be placed in different positions
constraint all_different(position);

% For each connection, compute the cable length as the distance between devices
array[1..num_connections] of var int: cable_lengths = 
    [ abs(position[connections[i,1]] - position[connections[i,2]]) * connections[i,3] | i in 1..num_connections ];

% Objective: minimize the total cable length
var int: final_sum = sum(i in 1..num_connections)(cable_lengths[i]);

solve minimize final_sum;

output [
    "{",
    "\"final_sum\": ", show(final_sum),
    "}"
];
```

