% For each number k (1..N), store its position (row, col)
array[1..N] of var 1..n: row;
array[1..N] of var 1..n: col;

% Each number appears exactly once in the grid
constraint
    all_different([x[i,j] | i in 1..n, j in 1..n]);

% Link x and (row,col) variables
constraint
    forall(i in 1..n, j in 1..n) (
        x[i,j] >= 1 /\ x[i,j] <= N /\
        row[x[i,j]] = i /\
        col[x[i,j]] = j
    );

% For each k = 2..N, enforce the movement rules
