      int: k = if i+2 > n then i+2-n else i+2
    } in
      x[i] + x[j] + x[k] <= 21
  );

solve satisfy;

output [
    "{",
    "\"x\": [" ++ join(",", [show(x[i]) | i in 1..n]) ++ "]",
    "}"
];
