constraint a * b == n * n;

% a - b = p
constraint a - b == p;

% p is prime
predicate is_prime(var int: x) =
    x > 1 /\
    forall(i in 2..ceil(sqrt(int2float(max(2,fix(x)))))) (
        x mod i != 0
    );

constraint is_prime(p);

% Find the smallest a
solve minimize a;

output [
    "{",
    "\"a\": ", show(a), ", ",
    "\"b\": ", show(b), ", ",
    "\"n\": ", show(n), ", ",
    "\"p\": ", show(p),
    "}"
];
