% Include the global constraints library
include "globals.mzn";

% Size of the grid
int: n = 31;
int: coins_per_row = 14;
int: coins_per_col = 14;

% Decision variables: x[i,j] = 1 if a coin is placed at cell (i,j), 0 otherwise
array[1..n, 1..n] of var 0..1: x;

% Constraint 1: Each row has exactly 14 coins
constraint
    forall(i in 1..n) (
        sum(j in 1..n)(x[i,j]) = coins_per_row
    );

% Constraint 2: Each column has exactly 14 coins
constraint
    forall(j in 1..n) (
        sum(i in 1..n)(x[i,j]) = coins_per_col
    );

% Constraint 4: At most one coin per cell (already enforced by x being 0/1)

% Objective: Minimize the sum of the squared horizontal distance from the main diagonal
% For cell (i,j), the horizontal distance from the main diagonal is abs(i-j)
% The quadratic distance is (i-j)^2

var int: z = sum(i in 1..n, j in 1..n)(x[i,j] * (i-j)*(i-j));

solve minimize z;

output [
    "{",
    "\"x\": [",
    join(",\n", [ "[" ++ join(",", [show(x[i,j]) | j in 1..n]) ++ "]" | i in 1..n ]),
    "],",
    "\"z\": ", show(z),
    "}"
];
