%   B A I J J A J I I A H F C F E B B J E A
% + D H F G A B C D I D B I F F A G F E J E
% = G J E G A C D D H F A F J B F I H E E F
%
% All letters are distinct digits.
% Print the number of each letter (A, B, C, D, E, F, G, H, I, J).

include "globals.mzn";

% List of all letters
set of int: LettersIdx = 1..10;
array[LettersIdx] of string: Letters = ["A","B","C","D","E","F","G","H","I","J"];

% Map letter to index for easy access
function int: idx(string: l) =
    if l == "A" then 1
    elseif l == "B" then 2
    elseif l == "C" then 3
    elseif l == "D" then 4
    elseif l == "E" then 5
    elseif l == "F" then 6
    elseif l == "G" then 7
    elseif l == "H" then 8
    elseif l == "I" then 9
    else 10 endif; % J

% Decision variables: digit assigned to each letter
array[LettersIdx] of var 0..9: digit;

% All letters are assigned distinct digits
constraint all_different(digit);

% The numbers as lists of letters (from left to right, most significant to least)
array[1..20] of string: add1_letters = ["B","A","I","J","J","A","J","I","I","A","H","F","C","F","E","B","B","J","E","A"];
array[1..20] of string: add2_letters = ["D","H","F","G","A","B","C","D","I","D","B","I","F","F","A","G","F","E","J","E"];
array[1..20] of string: sum_letters  = ["G","J","E","G","A","C","D","D","H","F","A","F","J","B","F","I","H","E","E","F"];

% Convert letter arrays to digit arrays
array[1..20] of var 0..9: add1_digits = [digit[idx(add1_letters[i])] | i in 1..20];
array[1..20] of var 0..9: add2_digits = [digit[idx(add2_letters[i])] | i in 1..20];
array[1..20] of var 0..9: sum_digits  = [digit[idx(sum_letters[i])]  | i in 1..20];

% No leading zeros
constraint add1_digits[1] != 0;
constraint add2_digits[1] != 0;
constraint sum_digits[1]  != 0;

% Model the addition column by column (right to left, i.e., least significant to most)
array[0..20] of var 0..1: carry; % carry[0] is 0, carry[20] is the final carry

constraint carry[0] = 0;

constraint
    forall(i in 1..20) (
        add1_digits[21-i] + add2_digits[21-i] + carry[i-1] = sum_digits[21-i] + 10 * carry[i]
    );

% The final carry must be 0 (since the sum has 20 digits)
constraint carry[20] = 0;

solve satisfy;

output [
    "{",
    join(",", [
        "\"A\": " ++ show(digit[idx("A")]),
        "\"B\": " ++ show(digit[idx("B")]),
        "\"C\": " ++ show(digit[idx("C")]),
