% Include the global constraints library
include "globals.mzn";

% Input data
int: num_warehouses = 4;
int: num_regions = 3;
set of int: WAREHOUSES = 1..num_warehouses;
set of int: REGIONS = 1..num_regions;

array[WAREHOUSES] of string: warehouse_s = ["New York", "Los Angeles", "Chicago", "Atlanta"];
array[WAREHOUSES] of int: fixed_costs = [400, 500, 300, 150];
int: max_shipping = 100;
array[REGIONS] of int: demands = [80, 70, 40];
array[WAREHOUSES, REGIONS] of int: shipping_costs = 
    array2d(WAREHOUSES, REGIONS, [
        20, 40, 50,   % New York to regions 1,2,3
        48, 15, 26,   % Los Angeles to regions 1,2,3
        26, 35, 18,   % Chicago to regions 1,2,3
        24, 50, 35    % Atlanta to regions 1,2,3
    ]);

% Decision variables
array[WAREHOUSES] of var 0..1: open_warehouse; % 1 if warehouse is open, 0 otherwise
array[WAREHOUSES, REGIONS] of var 0..max_shipping: ships; % units shipped from warehouse to region

% Constraints

% 1. If New York is open, Los Angeles must also be open
constraint open_warehouse[1] <= open_warehouse[2];

% 2. No more than three warehouses can be operational
constraint sum(w in WAREHOUSES)(open_warehouse[w]) <= 3;

% 3. Either Atlanta or Los Angeles must be open
constraint open_warehouse[2] + open_warehouse[4] >= 1;

% 4. Each region's demand must be met exactly
constraint forall(r in REGIONS)(
    sum(w in WAREHOUSES)(ships[w, r]) = demands[r]
);

% 5. Each warehouse can only ship if it is open, and cannot exceed max_shipping
constraint forall(w in WAREHOUSES)(
    sum(r in REGIONS)(ships[w, r]) <= max_shipping * open_warehouse[w]
);

% 6. No shipments from closed warehouses
constraint forall(w in WAREHOUSES, r in REGIONS)(
    ships[w, r] <= max_shipping * open_warehouse[w]
);

% Objective: Minimize total cost (fixed + shipping)
var int: total_cost = 
    sum(w in WAREHOUSES)(fixed_costs[w] * open_warehouse[w]) +
    sum(w in WAREHOUSES, r in REGIONS)(shipping_costs[w, r] * ships[w, r]);

solve minimize total_cost;

% Output in JSON format
output [
    "{",
    "\"total_cost\": ", show(total_cost), ", ",
    "\"open_warehouse\": [", join(",", [show(open_warehouse[w]) | w in WAREHOUSES]), "], ",
    "\"ships\": [",
        join(",", [
            "[" ++ join(",", [show(ships[w, r]) | r in REGIONS]) ++ "]"
            | w in WAREHOUSES
        ]),
    "]",
    "}"
];
```

