% Include necessary library
include "globals.mzn";

% Input data
int: num_moves = 3;
array[1..3] of int: init = [1, 0, 1]; % 1 = tails, 0 = heads

% There are 3 coins, indexed 1..3
int: num_coins = 3;

% Each move: which coin to flip (1..3)
array[1..num_moves] of var 1..num_coins: steps;

% State of coins after each move (0=heads, 1=tails)
array[0..num_moves, 1..num_coins] of var 0..1: state;

% Initial state
constraint forall(i in 1..num_coins) (
    state[0, i] = init[i]
);

% Apply moves: flipping the selected coin at each step
constraint forall(m in 1..num_moves, i in 1..num_coins) (
    state[m, i] = 
        if steps[m] = i then 1 - state[m-1, i] else state[m-1, i] endif
);

% Final state: all heads or all tails
constraint
    (forall(i in 1..num_coins)(state[num_moves, i] = 0) \/
     forall(i in 1..num_coins)(state[num_moves, i] = 1));

solve satisfy;

output [
    "{",
    "\"steps\": [" ++ join(",", [show(steps[m]) | m in 1..num_moves]) ++ "]",
    "}"
];
```

